28	  async function assertBoardCanAssignTasks(ctx: RequestCtx, companyId: string) {
29	    assertCompanyAccess(ctx, companyId);
30	    if (ctx.actor?.type !== "board") return;
31	    if (ctx.actor.source === "local_implicit" || ctx.actor.isInstanceAdmin) return;
32	    const allowed = await access.canUser(companyId, ctx.actor.userId, "tasks:assign");
33	    if (!allowed) {
34	      throw forbidden("Missing permission: tasks:assign");
35	    }
36	  }
37	
38	  function assertCanManageCompanyRoutine(ctx: RequestCtx, companyId: string, assigneeAgentId?: string | null) {
39	    assertCompanyAccess(ctx, companyId);
40	    if (ctx.actor?.type === "board") return;
41	    if (ctx.actor?.type !== "agent" || !ctx.actor.agentId) throw forbidden("Agent authentication required");
42	    if (assigneeAgentId !== ctx.actor.agentId) {
43	      throw forbidden("Agents can only manage routines assigned to themselves");
44	    }
45	  }
46	
47	  async function assertCanManageExistingRoutine(ctx: RequestCtx, routineId: string) {
48	    const routine = await svc.get(routineId);
49	    if (!routine) return null;
50	    assertCompanyAccess(ctx, routine.companyId);
51	    if (ctx.actor?.type === "board") return routine;
52	    if (ctx.actor?.type !== "agent" || !ctx.actor.agentId) throw forbidden("Agent authentication required");
53	    if (routine.assigneeAgentId !== ctx.actor.agentId) {
54	      throw forbidden("Agents can only manage routines assigned to themselves");
55	    }
56	    return routine;
57	  }
