68	  const createRoutine: Handler = async (ctx) => {
69	    const companyId = ctx.param("companyId") ?? "";
70	    const body = await ctx.json();
71	    const parsed = createRoutineSchema.parse(body);
72	    await assertBoardCanAssignTasks(ctx, companyId);
73	    assertCanManageCompanyRoutine(ctx, companyId, parsed.assigneeAgentId);
74	    const created = await svc.create(companyId, parsed, {
75	      agentId: ctx.actor?.type === "agent" ? (ctx.actor.agentId ?? null) : null,
76	      userId: ctx.actor?.type === "board" ? (ctx.actor.userId ?? "board") : null,
77	    });
78	
79	    // ctx.actor lacks `runId`; log with null runId.
80	    // TODO(cloudflare): thread runId through ActorContext.
81	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
82	    const actorId = ctx.actor!.type === "agent"
83	      ? (ctx.actor!.agentId ?? "unknown-agent")
84	      : (ctx.actor!.userId ?? "board");
85	    await logActivity(db, {
86	      companyId,
87	      actorType,
88	      actorId,
89	      agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
90	      runId: null,
91	      action: "routine.created",
92	      entityType: "routine",
93	      entityId: created.id,
94	      details: { title: created.title, assigneeAgentId: created.assigneeAgentId },
95	    });
96	    const telemetryClient = getTelemetryClient();
97	    if (telemetryClient) {
98	      trackRoutineCreated(telemetryClient);
99	    }
100	    return Response.json(created, { status: 201 });
101	  };
