115	  const patchRoutine: Handler = async (ctx) => {
116	    const id = ctx.param("id") ?? "";
117	    const routine = await assertCanManageExistingRoutine(ctx, id);
118	    if (!routine) {
119	      return Response.json({ error: "Routine not found" }, { status: 404 });
120	    }
121	    const body = await ctx.json();
122	    const parsed = updateRoutineSchema.parse(body);
123	    const assigneeWillChange =
124	      parsed.assigneeAgentId !== undefined &&
125	      parsed.assigneeAgentId !== routine.assigneeAgentId;
126	    if (assigneeWillChange) {
127	      await assertBoardCanAssignTasks(ctx, routine.companyId);
128	    }
129	    const statusWillActivate =
130	      parsed.status !== undefined &&
131	      parsed.status === "active" &&
132	      routine.status !== "active";
133	    if (statusWillActivate) {
134	      await assertBoardCanAssignTasks(ctx, routine.companyId);
135	    }
136	    if (
137	      ctx.actor?.type === "agent" &&
138	      parsed.assigneeAgentId !== undefined &&
139	      parsed.assigneeAgentId !== ctx.actor.agentId
140	    ) {
141	      throw forbidden("Agents can only assign routines to themselves");
142	    }
143	    const updated = await svc.update(routine.id, parsed, {
144	      agentId: ctx.actor?.type === "agent" ? (ctx.actor.agentId ?? null) : null,
145	      userId: ctx.actor?.type === "board" ? (ctx.actor.userId ?? "board") : null,
146	    });
147	
148	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
149	    const actorId = ctx.actor!.type === "agent"
150	      ? (ctx.actor!.agentId ?? "unknown-agent")
151	      : (ctx.actor!.userId ?? "board");
152	    await logActivity(db, {
153	      companyId: routine.companyId,
154	      actorType,
155	      actorId,
156	      agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
157	      runId: null,
158	      action: "routine.updated",
159	      entityType: "routine",
160	      entityId: routine.id,
161	      details: { title: updated?.title ?? routine.title },
162	    });
163	    return Response.json(updated);
164	  };
