388	export function routineRoutes(
389	  db: Db,
390	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
391	) {
392	  const router = Router();
393	  const {
394	    listRoutines,
395	    createRoutine,
396	    getRoutine,
397	    patchRoutine,
398	    listRoutineRuns,
399	    createRoutineTrigger,
400	    patchRoutineTrigger,
401	    deleteRoutineTrigger,
402	    rotateRoutineTriggerSecret,
403	    runRoutine,
404	    firePublicTrigger,
405	  } = buildHandlers(db, options);
406	
407	  const storageSentinel = new Proxy({} as StorageService, {
408	    get(_target, prop) {
409	      throw new Error(`routine handler unexpectedly accessed storage.${String(prop)}`);
410	    },
411	  });
412	  const deps = { db, storage: storageSentinel };
413	
414	  router.get("/companies/:companyId/routines", expressHandler(listRoutines, deps));
415	  router.post("/companies/:companyId/routines", expressHandler(createRoutine, deps));
416	  router.get("/routines/:id", expressHandler(getRoutine, deps));
417	  router.patch("/routines/:id", expressHandler(patchRoutine, deps));
418	  router.get("/routines/:id/runs", expressHandler(listRoutineRuns, deps));
419	  router.post("/routines/:id/triggers", expressHandler(createRoutineTrigger, deps));
420	  router.patch("/routine-triggers/:id", expressHandler(patchRoutineTrigger, deps));
421	  router.delete("/routine-triggers/:id", expressHandler(deleteRoutineTrigger, deps));
422	  router.post("/routine-triggers/:id/rotate-secret", expressHandler(rotateRoutineTriggerSecret, deps));
423	  router.post("/routines/:id/run", expressHandler(runRoutine, deps));
424	  router.post("/routine-triggers/public/:publicId/fire", expressHandler(firePublicTrigger, deps));
425	
426	  return router;
427	}
